INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Sind alle Arbeitsplatztypen fest an einen Ort gebunden?', 2, '[{"text": "Nein", "correct": true, "because": "Mobile Arbeitsplätze existieren"}, {"text": "Ja", "correct": false, "because": "Nicht alle ortsgebunden"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit der Wahl eines Arbeitsplatztyps?', 3, '[{"text": "Effizienz steigern", "correct": true, "because": "Passend zur Aufgabe"}, {"text": "Kosten senken", "correct": false, "because": "Indirekt"}, {"text": "Design verbessern", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Arbeitsplatztypen gibt es?', 5, '[{"text": "Büroarbeitsplatz", "correct": true, "because": "Klassischer Typ"}, {"text": "Heimarbeitsplatz", "correct": true, "because": "Flexibel"}, {"text": "Designstudio", "correct": false, "because": "Spezifische Ausstattung"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein mobiler Arbeitsplatz ist flexibel. b) Alle Arbeitsplätze brauchen Internet.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Internet nicht immer nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Wahl eines Arbeitsplatztyps?', 4, '[{"text": "Arbeitsaufgaben", "correct": false, "because": "Entscheidend für Typ"}, {"text": "Mitarbeiterbedürfnisse", "correct": false, "because": "Wichtig für Effizienz"}, {"text": "Bürofarbe", "correct": true, "because": "Irrelevant für Funktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Heimarbeitsplatz technische Ausstattung braucht?', 2, '[{"text": "Ja", "correct": true, "because": "PC und Internet oft nötig"}, {"text": "Nein", "correct": false, "because": "Abhängig, aber meist ja"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Arbeitsplatztyp ist für Teamarbeit geeignet?', 3, '[{"text": "Open-Office", "correct": true, "because": "Fördert Zusammenarbeit"}, {"text": "Heimarbeitsplatz", "correct": false, "because": "Isoliert"}, {"text": "Mobil", "correct": false, "because": "Flexibel, nicht teamorientiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Was gehört zu einem mobilen Arbeitsplatz?', 5, '[{"text": "Laptop", "correct": true, "because": "Tragbare Technik"}, {"text": "Internetzugang", "correct": true, "because": "Konnektivität"}, {"text": "Feste Büroausstattung", "correct": false, "because": "Nicht ortsgebunden"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Büroarbeitsplätze fördern Kommunikation. b) Alle Typen sind gleich teuer. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kosten variieren"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei Arbeitsplatztypen unwichtig?', 4, '[{"text": "Ergonomie", "correct": false, "because": "Wichtig für Gesundheit"}, {"text": "Technische Ausstattung", "correct": false, "because": "Entscheidend für Arbeit"}, {"text": "Firmenlogo", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist ein Open-Office-Arbeitsplatz immer laut?', 2, '[{"text": "Nein", "correct": true, "because": "Abhängig von Gestaltung"}, {"text": "Ja", "correct": false, "because": "Nicht zwangsläufig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein Heimarbeitsplatz?', 4, '[{"text": "Flexibilität", "correct": true, "because": "Ortsunabhängig"}, {"text": "Weniger Pendeln", "correct": true, "because": "Zeitersparnis"}, {"text": "Hohe Lautstärke", "correct": false, "because": "Kein Vorteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass mobile Arbeitsplätze keine Nachteile haben. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Konnektivität kann Problem sein"}, {"text": "Ja", "correct": false, "because": "Herausforderungen vorhanden"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Wahl eines Arbeitsplatztyps?', 3, '[{"text": "Arbeitsanforderungen", "correct": true, "because": "Bestimmt Typ"}, {"text": "Kosten", "correct": false, "because": "Sekundär"}, {"text": "Ästhetik", "correct": false, "because": "Weniger wichtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein Büroarbeitsplatz ist ortsgebunden. b) Mobile Arbeitsplätze brauchen keine Technik.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Technik für Mobil nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile hat ein Open-Office-Arbeitsplatz?', 5, '[{"text": "Lärmpegel", "correct": true, "because": "Kann ablenken"}, {"text": "Wenig Privatsphäre", "correct": true, "because": "Offene Struktur"}, {"text": "Hohe Flexibilität", "correct": false, "because": "Kein Nachteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einem Heimarbeitsplatz unwichtig?', 3, '[{"text": "Internetverbindung", "correct": false, "because": "Oft entscheidend"}, {"text": "Arbeitsgeräte", "correct": false, "because": "Nötig für Arbeit"}, {"text": "Bürofläche", "correct": true, "because": "Zuhause flexibel"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Fördert ein mobiler Arbeitsplatz die Produktivität?', 3, '[{"text": "Ja", "correct": true, "because": "Flexibilität hilft"}, {"text": "Nein", "correct": false, "because": "Abhängig, aber oft ja"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Büroarbeitsplatz Teamarbeit erleichtert?', 2, '[{"text": "Ja", "correct": true, "because": "Physische Nähe"}, {"text": "Nein", "correct": false, "because": "Fördert Zusammenarbeit"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Typ passt für kreative Aufgaben?', 4, '[{"text": "Einzelbüro", "correct": true, "because": "Ruhe fördert Kreativität"}, {"text": "Open-Office", "correct": false, "because": "Ablenkung möglich"}, {"text": "Mobil", "correct": false, "because": "Flexibel, aber unruhig"}]');
